Given an array of n elements and an integer m. The task is to find the maximum value of the sum of its subarray modulo m i.e find the sum of each subarray mod m and print the maximum value of this modulo operation.Examples: Input: arr[] = {10, 7, 18}, m = 13Output: 12Explanation: All subarrays and their modulo values:{10} => 10 mod  13 = 10{7} => 7 mod  13 = 7{18} => 18 mod  13 = 5{10, 7} => 17 mod  13 = 4{7, 18} => 25 mod  13 = 12{10, 7, 18} => 35 mod  13 = 9Input: arr[] = {3, 3, 9, 9, 5}, m = 7Output: 6Explanation: The subarray {3, 3} has maximum sub-array sum modulo 7. Try It YourselfTable of Content[Naive Approach] Checking All Subarrays - O(n^2) time and O(1) space[Efficient Approach] Using Prefix Sum - O(n log(n)) time and O(n) space[Naive Approach] Checking All Subarrays - O(n^2) time and O(1) spaceThe approach checks all possible subarrays, computes their sum modulo m, and tracks the highest remainder found.
            C++

    #include <bits/stdc++.h>
using namespace std;

// Function to find the maximum subarray sum modulo m
int maxSubMod(vector<int>& arr, int m) {
    int n = arr.size();
    int maxMod = 0;

    // Iterate over all possible subarrays
    for (int i = 0; i < n; i++) {
        int sum = 0;
        for (int j = i; j < n; j++) {

            // Compute sum of subarray arr[i...j]
            sum += arr[j];  

            // Update max modulo result
            maxMod = max(maxMod, sum % m);  
        }
    }
    return maxMod;
}

int main() {
    vector<int> arr = {3, 3, 9, 9, 5};
    int m = 7;
    cout << maxSubMod(arr, m) << endl;
    return 0;
}


