    import java.util.TreeSet;

public class Main {

    // Function to return the maximum subarray sum modulo m
    public static int maxSub(int[] arr, int m) {
        int pre = 0, maxMod = 0;
        TreeSet<Integer> prefixSet = new TreeSet<>();
        prefixSet.add(0);

        for (int num : arr) {
            pre = (pre + num % m) % m;
            maxMod = Math.max(maxMod, pre);

            // Find smallest prefix greater than current
            Integer higher = prefixSet.higher(pre);

            if (higher != null) {
                maxMod = Math.max(maxMod, (pre - higher + m) % m);
            }

            prefixSet.add(pre);
        }

        return maxMod;
    }

    public static void main(String[] args) {
        int[] arr = {3, 3, 9, 9, 5};
        int m = 7;
        System.out.println(maxSub(arr, m));  // Output: 6
    }
}


