    using System;
using System.Collections.Generic;

class Program
{
    static int MaxSub(int[] arr, int m)
    {
        int pre = 0, maxMod = 0;

        // SortedSet to store prefix sums in order
        SortedSet<int> prefixSet = new SortedSet<int>();
        prefixSet.Add(0);

        foreach (int num in arr)
        {
            pre = (pre + num % m) % m;
            maxMod = Math.Max(maxMod, pre);

            // Find the smallest element in prefixSet greater than pre
            foreach (int val in prefixSet)
            {
                if (val > pre)
                {
                    maxMod = Math.Max(maxMod, (pre - val + m) % m);
                    break;
                }
            }

            prefixSet.Add(pre);
        }

        return maxMod;
    }

    static void Main()
    {
        int[] arr = { 3, 3, 9, 9, 5 };
        int m = 7;
        Console.WriteLine(MaxSub(arr, m)); // Output: 6
    }
}


